import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as s,o as t,af as r,b as d,w as a,a as l,G as h,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"Site Boundaries and Knowledge Ownership","description":"The four-site ownership table — what learn-ai / Learn LLM / evals / sites-epub each own, what this repo keeps, what copying is forbidden; includes bridge metadata rules and accessibility verification for all three sibling sites.","frontmatter":{"title":"Site Boundaries and Knowledge Ownership","description":"The four-site ownership table — what learn-ai / Learn LLM / evals / sites-epub each own, what this repo keeps, what copying is forbidden; includes bridge metadata rules and accessibility verification for all three sibling sites.","domain":"tech","tags":["tech","orientation","ownership"],"navOrder":2,"topicId":"site-boundaries","layer":"0","status":"canonical","nodeType":"boundary","owner":"learn-ai","externalOwners":[],"prerequisites":["tech-map"],"next":["model-lifecycle-bridge"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/00-map/site-boundaries.md","filePath":"tech/00-map/site-boundaries.md","lastUpdated":1791166440000}'),p={name:"tech/00-map/site-boundaries.md"};function u(g,e,b,m,f,v){const i=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=r('<blockquote><p><strong>Group</strong>: 0 · Orientation and Boundaries | <strong>Previous group exit</strong>: none | <strong>This group exit</strong>: you can decide whether a piece of knowledge belongs here or at a sibling, and write a qualified bridge link <strong>Prerequisites</strong>: <a href="./../index.html">Tech Map</a> | <strong>Next</strong>: <a href="./../01-model-lifecycle/">Model Lifecycle (Bridge)</a> — the first full demonstration of the rules on this page</p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Lead with the answer</strong>: learn-ai is the single canonical owner of the cross-technology main line, not a second copy of any sibling site. Every piece of knowledge has exactly one body owner; when a sibling already covers a topic completely, this repo writes only &quot;why it affects the current engineering decision + stop point + next hop&quot;, never copying the body, full derivations, vendor long-form, or dynamic lists.</p><h3 id="mental-model-one-knowledge-point-one-owner" tabindex="-1">Mental model: one knowledge point, one owner <a class="header-anchor" href="#mental-model-one-knowledge-point-one-owner" aria-label="Permalink to &quot;Mental model: one knowledge point, one owner&quot;">​</a></h3>',4)),(t(),d(c,null,{default:a(()=>[h(i,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Q%5B%22A%20piece%20of%20knowledge%22%5D%20--%3E%20D%7B%22Who%20is%20the%20natural%20owner%3F%22%7D%0A%20%20%20%20D%20--%3E%7Ccross-tech%20main%20line%20%C2%B7%20decisions%20%C2%B7%20practice%7C%20LA%5B%22learn-ai%3Cbr%2F%3Ewrite%20the%20five-part%20canonical%22%5D%0A%20%20%20%20D%20--%3E%7Cmodel%20internals%20%C2%B7%20training%20math%7C%20LLM%5B%22Learn%20LLM%3Cbr%2F%3Ethis%20repo%20bridges%20only%22%5D%0A%20%20%20%20D%20--%3E%7Cevaluation%20methods%20%C2%B7%20release%20evidence%7C%20EV%5B%22evals%3Cbr%2F%3Ethis%20repo%20states%20when%20needed%22%5D%0A%20%20%20%20D%20--%3E%7Cvendor%20originals%20%C2%B7%20EPUB%7C%20EP%5B%22sites-epub%3Cbr%2F%3Ethis%20repo%20does%20second-pass%20work%22%5D%0A%20%20%20%20LA%20--%3E%20B%5B%22bridge%20record%3A%20stop%20point%20%2B%20canonicalUrl%20%2B%20retrievedAt%22%5D%0A%20%20%20%20LLM%20--%3E%20B%0A%20%20%20%20EV%20--%3E%20B%0A%20%20%20%20EP%20--%3E%20B%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="four-site-ownership-table" tabindex="-1">Four-site ownership table <a class="header-anchor" href="#four-site-ownership-table" aria-label="Permalink to &quot;Four-site ownership table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Owner</th><th>Owns (canonical)</th><th>This repo keeps</th><th>Copying forbidden</th></tr></thead><tbody><tr><td><strong>learn-ai</strong> (this repo)</td><td>Cross-technology main line, five-part chapters, symptom decision tree, minimal keyless fixtures, debugging / production experience</td><td>—</td><td>Never a second canonical for any sibling</td></tr><tr><td><strong>Learn LLM</strong></td><td>Model internals, training math, low-level RAG / agent principles</td><td>Decision impact + stop point + deep link</td><td>Full derivations, training experiment details</td></tr><tr><td><strong>evals</strong></td><td>Evaluation methods, benchmarks, scorers / judges, release evidence and eval pipelines</td><td>When evidence is needed; how release gates plug in</td><td>Eval pipeline implementations, benchmark data</td></tr><tr><td><strong>sites-epub</strong></td><td>Vendor docs / blog captures, EPUB indexing</td><td>Second-pass treatment of stable cross-vendor concepts + reading routes</td><td>Vendor long-form, dynamic command / parameter / plan lists</td></tr></tbody></table><h3 id="decision-table-where-a-piece-of-content-goes" tabindex="-1">Decision table: where a piece of content goes <a class="header-anchor" href="#decision-table-where-a-piece-of-content-goes" aria-label="Permalink to &quot;Decision table: where a piece of content goes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimension</th><th>Write here</th><th>Bridge to sibling</th></tr></thead><tbody><tr><td>Direction</td><td>Main-line knowledge that shapes engineering decisions</td><td>Deep principles and methodology</td></tr><tr><td>Control</td><td>This repo&#39;s authors can maintain and accept it</td><td>Maintained by the sibling&#39;s authors and pipeline</td></tr><tr><td>State</td><td>Stable concepts, slow to drift</td><td>Dynamic numbers (chapter counts, prices, model lists)</td></tr><tr><td>Trust domain</td><td>This repo&#39;s reputation</td><td>The sibling&#39;s canonical standing</td></tr><tr><td>Lowest complexity</td><td>One bridge table + stop point</td><td>—</td></tr></tbody></table><p>Historical milestones: the four-site split was frozen in 2026-09 with Issue #116; previously the &quot;Learn LLM chapter links&quot; were scattered across pages, and this page consolidates them into the single ownership rule page.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>This page is a rules page with no runnable code artifact; &quot;Usage&quot; = bridge-link drills (≤15 minutes, pen and paper). Acceptance: write one qualified bridge for each of three real topics.</p><h3 id="stop-point-and-next-hop-per-site" tabindex="-1">Stop point and next hop per site <a class="header-anchor" href="#stop-point-and-next-hop-per-site" aria-label="Permalink to &quot;Stop point and next hop per site&quot;">​</a></h3><p><strong>Learn LLM</strong> (<a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">https://llm.zenheart.site/</a>)</p><ul><li>Example stop point: stop at &quot;the KV cache sets the order of magnitude of the context budget&quot;; do not derive attention complexity.</li><li>Next-hop format: link the concrete chapter path (e.g. <code>https://llm.zenheart.site/chapters/09-inference-cache</code>), not the homepage.</li></ul><p><strong>evals</strong> (<a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a>)</p><ul><li>Example stop point: stop at &quot;you need replayable evidence before shipping&quot;; do not cover judge construction or benchmark design.</li><li>Next-hop format: a concrete chapter under <code>https://evals.zenheart.site/book/</code>.</li></ul><p><strong>sites-epub</strong> (<a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">https://epub.zenheart.site/</a>)</p><ul><li>Example stop point: stop at &quot;this concept originates from a vendor document&quot;; do not copy vendor commands and parameters.</li><li>Next-hop format: the site&#39;s index page; the site is currently unreachable over HTTPS (see the verification table below) — re-check before citing.</li></ul><h3 id="drill-write-one-qualified-bridge" tabindex="-1">Drill: write one qualified bridge <a class="header-anchor" href="#drill-write-one-qualified-bridge" aria-label="Permalink to &quot;Drill: write one qualified bridge&quot;">​</a></h3><p>Using &quot;the vector geometry of embeddings&quot; as the topic:</p><ol><li><strong>Assign the owner</strong>: math and training objectives → Learn LLM.</li><li><strong>Find the canonical concrete path</strong>: <code>https://llm.zenheart.site/chapters/11-rag</code> (not the homepage).</li><li><strong>Record retrievedAt</strong>: 2026-09-01, HTTP 200.</li><li><strong>Write the stop point and next hop</strong>: &quot;This repo stops at &#39;embeddings turn semantics into comparable vectors&#39;; space geometry and training objectives: Learn LLM chapter 11.&quot;</li></ol><p><strong>Negative example</strong>: writing only &quot;see Learn LLM&quot; with a homepage link — the reader cannot verify the target chapter exists nor tell when the content expired.</p><h3 id="site-accessibility-verification-table" tabindex="-1">Site accessibility verification table <a class="header-anchor" href="#site-accessibility-verification-table" aria-label="Permalink to &quot;Site accessibility verification table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Site</th><th>URL</th><th>Status</th><th>retrievedAt</th></tr></thead><tbody><tr><td>Learn LLM</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">https://llm.zenheart.site/</a></td><td>HTTP 200, normal</td><td>2026-09-01</td></tr><tr><td>Learn LLM chapter index</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/</a></td><td>HTTP 200, 21-chapter map readable</td><td>2026-09-01</td></tr><tr><td>evals</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>HTTP 200, normal</td><td>2026-09-01</td></tr><tr><td>evals reading entry</td><td><a href="https://evals.zenheart.site/book/" target="_blank" rel="noreferrer">https://evals.zenheart.site/book/</a></td><td>HTTP 200</td><td>2026-09-01</td></tr><tr><td>sites-epub</td><td><a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">https://epub.zenheart.site/</a></td><td><strong>warning</strong>: TLS certificate mismatch (serves a <code>*.github.com</code> certificate); HTTPS currently unreachable</td><td>2026-09-01</td></tr></tbody></table><p>The sites-epub ownership declaration remains in force (see <code>_phase0/bridge-register.md</code>), but any citation must first re-check the site&#39;s recovery; this repo writes no content assertions based on an unreachable site.</p><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><h3 id="why-one-knowledge-point-has-one-owner" tabindex="-1">Why one knowledge point has one owner <a class="header-anchor" href="#why-one-knowledge-point-has-one-owner" aria-label="Permalink to &quot;Why one knowledge point has one owner&quot;">​</a></h3><p>The cost of copying a body is not storage but <strong>drift</strong>: after the sibling updates, this repo&#39;s copy silently expires; readers see two versions and cannot tell which is trustworthy; audits double. The SSOT (single source of truth) principle replaces copying with <strong>verifiable pointers</strong>: canonicalUrl + retrievedAt + stop point.</p><h3 id="why-dynamic-numbers-stay-out-of-this-repo" tabindex="-1">Why dynamic numbers stay out of this repo <a class="header-anchor" href="#why-dynamic-numbers-stay-out-of-this-repo" aria-label="Permalink to &quot;Why dynamic numbers stay out of this repo&quot;">​</a></h3><p>Chapter counts, prices, availability, and model lists all change. Copying them statically plants data that expires on a timer. The rule: such facts record only the URL and retrievedAt; the body carries the stable conclusion (&quot;the site&#39;s current state prevails&quot;).</p><h3 id="bridge-metadata-fields" tabindex="-1">Bridge metadata fields <a class="header-anchor" href="#bridge-metadata-fields" aria-label="Permalink to &quot;Bridge metadata fields&quot;">​</a></h3><p>Every cross-site hop records at least:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>canonicalTopicId</td><td>The topic ID on this repo&#39;s side</td><td><code>context</code></td></tr><tr><td>owner</td><td>The canonical site of the deep content</td><td>Learn LLM</td></tr><tr><td>Stop point</td><td>Where this repo&#39;s body stops</td><td>&quot;The KV cache limits the context budget&quot;</td></tr><tr><td>canonicalUrl</td><td>The target&#39;s concrete path (not the homepage)</td><td><code>https://llm.zenheart.site/chapters/09-inference-cache</code></td></tr><tr><td>sourceCommitOrVersion</td><td>The target content&#39;s version (when available)</td><td>chapter revision; otherwise &quot;not provided&quot;</td></tr><tr><td>prerequisites / nextQuestion</td><td>The reader&#39;s question before / after the hop</td><td>&quot;Why is there a context budget&quot; / &quot;how to compress context&quot;</td></tr><tr><td>lastVerified / retrievedAt</td><td>Latest verification date</td><td>2026-09-01</td></tr></tbody></table><p>The full register is maintained in-repo at <code>_phase0/bridge-register.md</code> (an engineering artifact, not published with the site); public pages carry only its URLs and stop points.</p><h3 id="specification-vs-local-measurement" tabindex="-1">Specification vs local measurement <a class="header-anchor" href="#specification-vs-local-measurement" aria-label="Permalink to &quot;Specification vs local measurement&quot;">​</a></h3><p>This page has no protocol specification. The &quot;local measurement&quot; is the verification table above; re-verification means issuing one HTTPS request to the target URL and confirming 200 plus a valid certificate.</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>This page has no code integration; &quot;Development&quot; = runbooks for ownership conflicts and link rot.</p><h3 id="symptom-→-evidence-→-action-→-done" tabindex="-1">Symptom → Evidence → Action → Done <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done&quot;">​</a></h3><p><strong>Symptom</strong>: the same topic has two bodies — here versus a sibling (or two pages here). <strong>Evidence</strong>: a content audit finds duplicated exposition, or the two versions disagree. <strong>Action</strong>: assign the canonical owner — main-line decisions to this repo, deep principles to the sibling; the loser becomes a bridge (stop point + next hop kept) or a redirect. <strong>Done</strong>: the topic has exactly one topicId and one body; the bridge register and redirects.json are updated in sync.</p><h3 id="symptom-→-evidence-→-action-→-done-1" tabindex="-1">Symptom → Evidence → Action → Done <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-1" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done&quot;">​</a></h3><p><strong>Symptom</strong>: a sibling deep link in a resource library 404s or no longer matches. <strong>Evidence</strong>: retrievedAt older than a quarter; the request returns non-200. <strong>Action</strong>: re-locate the canonical path on the sibling site, update canonicalUrl and retrievedAt; if no equivalent exists, downgrade to a homepage link labeled &quot;concrete chapter not located&quot;. <strong>Done</strong>: the link returns 200 and the anchored content still supports the original claim.</p><h3 id="symptom-→-evidence-→-action-→-done-2" tabindex="-1">Symptom → Evidence → Action → Done <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-2" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done&quot;">​</a></h3><p><strong>Symptom</strong>: a sibling site is wholly unreachable (currently the case for sites-epub). <strong>Evidence</strong>: HTTPS requests fail or the certificate mismatches. <strong>Action</strong>: mark a warning with retrievedAt on affected pages; keep the ownership record; add no content assertions based on that site. <strong>Done</strong>: update the status row once the site returns 200; zero new citations in the interim.</p><h3 id="anti-pattern-list" tabindex="-1">Anti-pattern list <a class="header-anchor" href="#anti-pattern-list" aria-label="Permalink to &quot;Anti-pattern list&quot;">​</a></h3><ul><li>&quot;See site X&quot; plus a homepage link: an unverifiable, unauditable bridge.</li><li>Translating / summarizing sibling chapters into this repo: creating a second canonical.</li><li>Statically copying dynamic numbers (chapter counts, prices, model lists): planting timed-expiry data.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><ul><li><strong>Beginner</strong>: read the four-site table; decide &quot;where does this content go&quot; correctly.</li><li><strong>Builder</strong>: write your first qualified bridge (see the Usage drill) and have it reviewed.</li><li><strong>Operator</strong>: maintain a topic cluster&#39;s bridge records; re-verify retrievedAt quarterly.</li><li><strong>Researcher</strong>: read the sibling sites&#39; structures and understand their knowledge positions.</li></ul><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Evidence level</th><th>Canonical URL</th><th>Purpose</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>Learn LLM</td><td>sibling</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">https://llm.zenheart.site/</a></td><td>Canonical for model internals</td><td>Deep principles belong there (retrievedAt 2026-09-01, HTTP 200)</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Chapter index</a></td></tr><tr><td>evals</td><td>sibling</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>Canonical for evaluation methodology</td><td>Evaluation belongs there (retrievedAt 2026-09-01, HTTP 200)</td><td><a href="https://evals.zenheart.site/book/" target="_blank" rel="noreferrer">Reading entry</a></td></tr><tr><td>evals source repo</td><td>sibling</td><td><a href="https://github.com/zenHeart/evals" target="_blank" rel="noreferrer">https://github.com/zenHeart/evals</a></td><td>Content source of the evals site</td><td>Repo-to-site correspondence (retrievedAt 2026-09-01, HTTP 200)</td><td>—</td></tr><tr><td>sites-epub</td><td>sibling</td><td><a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">https://epub.zenheart.site/</a></td><td>Canonical for vendor originals and EPUB</td><td>Ownership in force but site currently unreachable (retrievedAt 2026-09-01, warning)</td><td>Re-verify after recovery</td></tr></tbody></table><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: if a sibling-covered topic carries a long body here (instead of a bridge), this page&#39;s rules failed in execution — file a migration instead of adding more.</li><li>Open: the sites-epub HTTPS recovery time is unknown; until then, reading routes depending on it use Learn LLM / evals as substitute entries.</li><li>Open: the <code>sourceCommitOrVersion</code> field is unavailable on most sibling pages; record &quot;not provided&quot; uniformly and upgrade once siblings expose stable version identifiers.</li></ul><h3 id="where-learn-ai-stops-where-to-continue" tabindex="-1">Where learn-ai stops / where to continue <a class="header-anchor" href="#where-learn-ai-stops-where-to-continue" aria-label="Permalink to &quot;Where learn-ai stops / where to continue&quot;">​</a></h3><ul><li>Next demonstration in this repo: <a href="./../01-model-lifecycle/">Model Lifecycle (Bridge)</a> — a complete bridge page written under this page&#39;s rules.</li><li>Deep model principles: <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>.</li><li>Evaluation methodology: <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>.</li></ul><h2 id="resource-evidence-levels-tree-wide-legend" tabindex="-1">Resource evidence levels (tree-wide legend) <a class="header-anchor" href="#resource-evidence-levels-tree-wide-legend" aria-label="Permalink to &quot;Resource evidence levels (tree-wide legend)&quot;">​</a></h2><p>The &quot;level&quot; column in each page&#39;s resource library uses these letters (a few historical pages drift by ±1; this table is authoritative):</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning</th><th>Typical source</th></tr></thead><tbody><tr><td>E</td><td>Local empirical evidence</td><td>measurable output of this repo&#39;s fixtures</td></tr><tr><td>L0</td><td>Official spec / first-party implementation</td><td>protocol specs, SDK source, changelogs</td></tr><tr><td>L1</td><td>Official maintainer narrative</td><td>official docs, official engineering blogs</td></tr><tr><td>L2</td><td>Authoritative secondary</td><td>well-known engineering books, surveys</td></tr><tr><td>L4</td><td>Background signal</td><td>community threads, unattributed posts (leads only)</td></tr><tr><td>sibling</td><td>Sibling-site canonical</td><td>Learn LLM / evals / sites-epub</td></tr></tbody></table>',54))])}const L=n(p,[["render",u]]);export{x as __pageData,L as default};
